var ECOLE_VERS_CLASSE = {"irons_spellbooks:fire": "Pyromancien", "irons_spellbooks:ice": "Cryomancien", "irons_spellbooks:lightning": "Électro-Sorcier", "irons_spellbooks:holy": "Paladin", "irons_spellbooks:blood": "Hémomancien", "irons_spellbooks:ender": "Voyageur du Vide", "irons_spellbooks:nature": "Druide", "irons_spellbooks:evocation": "Évocateur", "chronomancy:chronomancy": "Chronomancien", "gtbcs_geomancy_plus:geo": "Géomancien", "cataclysm_spellbooks:sand": "Aéromancien / Géomancien", "wind_spellbooks:wind": "Aéromancien", "colormagic:color_magic": "Chromancien", "aces_spell_utils:hydro": "Hydromancien", "somakespells:aqua": "Hydromancien", "cataclysm_spellbooks:abyssal": "Hydromancien", "monsterspellbooks:necro": "Nécromancien", "cursed_school:cursed": "Réprouvé", "cursespells:curse": "Envoûteur", "esoteric_spell:esoteric": "Ésotériste", "asterismarcanum:astral": "Astromancien", "tempest_almanac:astral": "Astromancien", "iss_magicfromtheeast:spirit": "Spiritualiste", "iss_magicfromtheeast:symmetry": "Symétriste", "aces_spell_utils:technomancy": "Technomancien", "cataclysm_spellbooks:technomancy": "Technomancien", "irons_spellbooks:eldritch": "toutes"}
var MONDE_PRET = false
var rechargeDans = -1
var SpellRegistryL = null
var ResLocL = null
function classeReelle(id) {
  try {
    if (!SpellRegistryL) {
      SpellRegistryL = Java.loadClass('io.redspace.ironsspellbooks.api.registry.SpellRegistry')
      ResLocL = Java.loadClass('net.minecraft.resources.ResourceLocation')
    }
    var sort = SpellRegistryL.getSpell(ResLocL.tryParse(id))
    if (!sort) return null
    var ecole = String(sort.getSchoolType().getId())
    // Iron's répond « évocation » par défaut quand l'école d'un sort n'est pas reconnue :
    // on ne fait jamais confiance à cette réponse (le titre statique est conservé).
    if (ecole === 'irons_spellbooks:evocation') return null
    var c = ECOLE_VERS_CLASSE[ecole]
    return c ? c : null
  } catch (e) { return null }
}
function corrigerClasse(ns, cle, valeur) {
  try {
    var m = /^spell\.([^.]+)\.([^.]+)(\.guide)?$/.exec(cle)
    if (!m) return valeur
    var id = m[1] + ':' + m[2]
    if (SORTS_SPECIAUX.indexOf(id) !== -1) return valeur
    var c = classeReelle(id)
    if (!c) return valeur
    if (m[3]) return String(valeur).replace(/^§6Classe : [^§]*§r/, '§6Classe : ' + c + '§r')
    return String(valeur).replace(/^\[[^\]]*\] /, '[' + c + '] ')
  } catch (e) { return valeur }
}

function ajouterTextes(langue) {
  var event_ = null
  ClientEvents.lang(langue, function (event) {
    var parNs = TEXTES[langue]
    var n = 0
    for (var ns in parNs) {
      var cles = parNs[ns]
      for (var k in cles) {
        var valeur = corrigerClasse(ns, k, cles[k])
        if (langue === 'en_us') valeur = traduireEN(valeur)
        event.add(ns, k, valeur)
        n++
      }
    }
    console.info('[classes_langue] ' + langue + ' : ' + n + ' textes ajoutés.')
  })
}

try {
  ajouterTextes('en_us')
  ajouterTextes('fr_fr')
} catch (e) {
  console.error('[classes_langue] ClientEvents.lang indisponible : ' + e)
}

// Écrit dans client.log les sorts dont la classe du titre diffère de l'école réelle en jeu.
function auditerClasses() {
  var cles = TEXTES['fr_fr']
  var ecarts = 0
  var inconnus = 0
  var total = 0
  for (var ns in cles) {
    var kv = cles[ns]
    for (var k in kv) {
      var m = /^spell\.([^.]+)\.([^.]+)$/.exec(k)
      if (!m) continue
      total++
      var id = m[1] + ':' + m[2]
      if (SORTS_SPECIAUX.indexOf(id) !== -1) continue
      var p = /^\[([^\]]*)\] /.exec(String(kv[k]))
      var statique = p ? p[1] : '?'
      var reel = classeReelle(id)
      if (!reel) { inconnus++; console.info('[classes_langue] ECOLE-INCONNUE ' + id + ' (titre : ' + statique + ')'); continue }
      if (reel !== statique) { ecarts++; console.info('[classes_langue] ECART ' + id + ' : titre statique ' + statique + ' -> classe réelle ' + reel) }
    }
  }
  console.info('[classes_langue] AUDIT : ' + total + ' sorts, ' + ecarts + ' écarts corrigés, ' + inconnus + ' à école inconnue.')
}

// ── Les écoles réelles des sorts ne sont connues qu'une fois en jeu (config du serveur) ──
// On recharge donc les textes une fois connecté, pour que [Classe] suive la vraie école.
try {
  ClientEvents.loggedIn(function (event) {
    MONDE_PRET = true
    rechargeDans = 100
  })
} catch (e) { console.error('[classes_langue] loggedIn indisponible : ' + e) }
try {
  ClientEvents.loggedOut(function (event) {
    MONDE_PRET = false
    rechargeDans = -1
  })
} catch (e) { console.error('[classes_langue] loggedOut indisponible : ' + e) }
try {
  ClientEvents.tick(function (event) {
    if (rechargeDans > 0) {
      rechargeDans--
      if (rechargeDans === 0) {
        try { auditerClasses() } catch (e3) { console.error('[classes_langue] audit impossible : ' + e3) }
        try {
          Java.loadClass('net.minecraft.client.Minecraft').getInstance().reloadResourcePacks()
          console.info('[classes_langue] textes rechargés avec les écoles réelles.')
        } catch (e2) { console.error('[classes_langue] rechargement impossible : ' + e2) }
      }
    }
  })
} catch (e) { console.error('[classes_langue] tick indisponible : ' + e) }
